G=load(); print(sorted(G))
for name in ['Demo pair 1 input','Demo pair 2 input','Demo pair 3 input']:
    i=np.array(G[name]); H,W=i.shape
    bg=max(Counter(i.flatten().tolist()),key=lambda c:(c[1],[]))
    bg=int(bg[0]); cnt=int(bg[1])
    # non-background components (4-conn), largest
    comp=[]
    seen=np.zeros_like(i,bool)
    def nbrs(a,b):
        for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
            y,x=a+da,b+db
            if 0<=y<H and 0<=x<W and not seen[y,x] and i[y,x]!=bg:
                yield (y,x)
    for y in range(H):
        for x in range(W):
            if not seen[y,x] and i[y,x]!=bg:
                stack=[(y,x)]; seen[y,x]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for p in nbrs(a,b):
                        if not seen[p[0],p[1]]: seen[p[0],p[1]]=True; stack.append(p)
                comp.append(cells)
    comp.sort(key=len,reverse=True)
    c=comp[0]
    ys=[a for a,b in c]; xs=[b for a,b in c]
    sides={'TL':min(ys), 'TR':max(ys), 'BL':min(xs),'BR':max(xs)}
